import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { name4Schema, type Name4 } from "./unions/name4.js";
import { profileidSchema, type Profileid } from "./unions/profileid.js";

export type PazeClient = {
  /** Client identifier generated by Paze and shared during onboarding. */
  id: string;
  /** Display name associated with the client for presentation purposes. */
  name?: Name4;
  /** Client profile to use during checkout. */
  profileId?: Profileid;
};

export const pazeClientSchema: Schema<PazeClient> = s.object<PazeClient>({
  id: s.string(),
  name: s.optional(s.lazy(() => name4Schema)),
  profileId: s.optional(s.lazy(() => profileidSchema)),
});
